function createBaseOrderbookSequence(): OrderbookSequence {
  return { sequence: 0, marketId: "" };
}

export const OrderbookSequence: MessageFns<OrderbookSequence> = {
  encode(message: OrderbookSequence, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.sequence !== 0) {
      writer.uint32(8).uint64(message.sequence);
    }
    if (message.marketId !== "") {
      writer.uint32(18).string(message.marketId);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): OrderbookSequence {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseOrderbookSequence();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 8) {
            break;
          }

          message.sequence = longToNumber(reader.uint64());
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.marketId = reader.string();
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): OrderbookSequence {
    return {
      sequence: isSet(object.sequence) ? globalThis.Number(object.sequence) : 0,
      marketId: isSet(object.marketId)
        ? globalThis.String(object.marketId)
        : isSet(object.market_id)
        ? globalThis.String(object.market_id)
        : "",
    };
  },

  toJSON(message: OrderbookSequence): unknown {
    const obj: any = {};
    if (message.sequence !== 0) {
      obj.sequence = Math.round(message.sequence);
    }
    if (message.marketId !== "") {
      obj.marketId = message.marketId;
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<OrderbookSequence>, I>>(base?: I): OrderbookSequence {
    return OrderbookSequence.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<OrderbookSequence>, I>>(object: I): OrderbookSequence {
    const message = createBaseOrderbookSequence();
    message.sequence = object.sequence ?? 0;
    message.marketId = object.marketId ?? "";
    return message;
  },
};

